submitJobs enqueues an internal computeSquare mutation with `{ input: -1 }`, `context: String(input)` and the callback below. computeSquare throws for -1. There are no retries or cancellations. Only this callback writes receipts.

```ts
export const recordReceipt = internalMutation({
  args: vOnCompleteArgs(v.string()),
  handler: async (ctx, args) => {
    await ctx.db.insert("receipts", {
      jobKey: args.context,
      kind: args.result.kind === "success" ? "success" : "failed",
      value:
        args.result.kind === "success"
          ? (args.result.returnValue as number)
          : null,
    });
  },
});
```
